    /**
     * Timeout for sending messages.
     * 发送消息默认超时时间， 默认 3s
     */
    private int sendMsgTimeout = 3000;

    /**
     * Compress message body threshold, namely, message body larger than 4k will be compressed on default.
     * 启用消息压缩的阈值，默认4K
     */
